<script>
export default {
  props: {
    isVisible: {
      type: Boolean,
      default: false
    },
    isDir: {
      type: Boolean,
      default: false
    }
  },
  emits: ['create', 'cancel'],
  data() {
    return {
      fileName: '',
      fileExtension: '',
      error: null
    }
  },
  watch: {
    isVisible(newVal) {
      if (newVal) {
        this.fileName = ''
        this.fileExtension = ''
        this.error = null
        this.$nextTick(() => this.$refs.inputRef?.focus())
      }
    }
  },
  methods: {
    onSubmit() {
      this.error = null

      if (!this.fileName.trim()) {
        this.error = 'Name cannot be empty'
        return
      }

      const name = this.fileName.trim()
      const ext = this.fileExtension.trim()

      if (!this.isDir && name.includes('.')) {
        this.error = 'File name should not include extension in the name field'
        return
      }

      const fullName = ext ? `${name}.${ext}` : name

      this.$emit('create', {
        name: fullName,
        displayName: name
      })

      this.fileName = ''
      this.fileExtension = ''
    },
    onCancel() {
      this.$emit('cancel')
      this.fileName = ''
      this.fileExtension = ''
      this.error = null
    }
  }
}
</script>
