  data() {
    return {
      // Which panel is visible in single-panel mode: 'tree' | 'file'
      mobileView: 'tree',
      // Whether any file is currently open. When false the file tree takes the
      // full width on every viewport (desktop hides the file panel too).
      hasOpenFiles: false,
      splitterConfig: {
        left: {
          minSize: 15,
          defaultSize: 25,
          collapsible: true
        },
        right: {
          minSize: 15,
          defaultSize: 75,
          collapsible: true
        }
      }
    }
