    }
  },
  methods: {
    // Open a new file tab. On desktop the file panel is mounted on demand
    // (see hasOpenFiles), so we wait a tick for the TabManager ref to exist.
    async openTab(tab) {
      this.hasOpenFiles = true
      await this.$nextTick()
      if (this.$refs.tabManager) {
