  archive(sources, { archivePath = null, format = null, overwrite = false } = {}) {
    return API.post(`/api/files/archive`, {
      sources: toPathList(sources),
      archive_path: archivePath,
      format,
      overwrite
    }).then((result) => {
      invalidatePath(API, result?.abs_archive_path)
      return result
    })
  },

